; 2026-10-16 (runs/maps-pm mkmaps3.py): font-pairing picks 1(8-bit)=maruf-marus-24-1, 1(TC)=maruf-marus-24-aa, 40(8-bit)=jamo2-nsqrr-36-1, 40(TC)=jamo2-nsqrr-36-aa, 41(8-bit)=jamo2-nsqrb-36-1, 41(TC)=jamo2-nsqrb-36-aa, 7(8-bit)=dkb-hangul40-1, 7(TC)=dkb-hangul40-1, 8(8-bit)=cur-munjo24, 8(TC)=cur-munjo24 (first in the chain; English original)
; Laura Bow 1 (The Colonel's Bequest), Korean UTF-8 translation (GAMES\LB1KO:
; MESSAGE.MAP + RESOURCE.MSG, packed text resources + SCI-KO.STR,
; language=ko). One map, two presets; the ini's render_target picks one.
;
; LB1's font ids, their line height in hi-res px and the game baseline row:
;   0   status/menu bar, parser line, system dialogs    16  row 14
;   1   large message boxes ("막이 오르려")              24  row 16
;   4   dialogue, narration, copy-protection screen      18  row 14
;   8   cast names under the intro portraits             24  row 20
;   40  the "1925 / LA 뉴올리언스" caption               36  row 30
;   41  opening credits and act titles ("제I막")        36  row 30
;
; Default (true colour: render_target=auto, on DOS rgb565 unless only rgb888 has 640x400; or set rgb565 or rgb888): two faces,
; picked by the font id:
;   body - GBATB17.SVF, Gowun Batang Bold 17 px, 2 bpp: fonts 1, 4, 8, 40, 41;
;   ui   - NGOTB16.SVF, NanumGothic-Bold 16 px, 2 bpp: font 0 and any other id.
; Both are baked on one baseline in a 16x16 cell (--clip-cell); align=cell
; puts every glyph on its line with no offset, so no ink lies outside the
; line the game erases. blend=auto anti-aliases the 2 bpp faces on a
; true-colour screen; with them in the bare sections, render_target=auto
; picks true colour.
;
; render_target=clut8 (8-bit palette): hard-edged 1 bpp faces, one per font id, the user's
; pairing picks (2026-10-15):
;   0   HTERM16.SVF   hanterm-font 3.1 h01.bdf, 16 px jamo set, ascent 14
;   1   HWPHM24.SVF   HWP 1.x HANGUL1.PFT, 24 px serif jamo set
;   4   IYAGI16.SVF   Iyagi IYG.KOR, 16 px jamo set (also any other id: 999 debug)
;   7   TBGHC48.SVF   Taebaek GHANC48, 48 px jamo set (the printer font; the id is not drawn in play)
;   8   MUNJO24.SVF   Mac HangulTalk 1.0 Munjo24, 24 px jamo set (mac-fbit-45sets: 8 lead classes, 20 initial sets)
;   40      DIPHY36.SVF  Diphylleia 36 px, 1 bpp precomposed (user pick; no 30-36 px jamo strike exists): the 1925 caption
;   41      YOUTH36.SVF  Youth (청춘체) 36 px, 1 bpp precomposed: opening credits, act titles
; Both stream and preload (DIPHY36.HOT, YOUTH36.HOT: the Hangul each font draws). One-game faces: they sit in the game folder of the LB1 pack.
; The game's own font draws every basic-Latin character (range.basic-latin=original, game widths): the
; faces carry Hangul only (the sets compose all 11,172). Faces of 24 px and up set size= and cell=glyph, so the
; layout cell is the face's (a face taller than 16 px drawn in the 16 px game cell lands off its pen).
; MUNJO24 needs an engine with JSET limits 8 lead classes / 24 initial sets (older ones skip it: SANGAM16 draws font 8).
; The jamo sets are in the jamo font pack (the engine zip leaves them out): SANGAM16.SVF (fb), the
; engine's fallback, is the last face of each chain and draws the text if the pack is missing.
; Characters no face has draw U+25A1. LB1's translation needs nothing
; outside the 2350 Hangul.
[map]
version=2

[render]
scale=2
blend=auto
[render:clut8]
blend=off

[fonts]
ui=NGOTB16.SVF
body=GBATB17.SVF
munjo=MUNJO24.SVF
fb=SANGAM16.SVF
marus24a=MARUS24A.SVF
nsqrr36a=NSQRR36A.SVF
nsqrb36a=NSQRB36A.SVF
dkbhg40=DKBHG40.SVF
[fonts:clut8]
; the 8-bit preset: one 1 bpp face per font id (the 16 px SANGAM16.SVF is every chain's fallback)
hterm=HTERM16.SVF
hwp=HWPHM24.SVF
iyagi=IYAGI16.SVF
munjo=MUNJO24.SVF
cap=DIPHY36.SVF
credit=YOUTH36.SVF
gh48=TBGHC48.SVF
fb=SANGAM16.SVF
marus24=MARUS24.SVF
nsqrr36=NSQRR36.SVF
nsqrb36=NSQRB36.SVF
dkbhg40=DKBHG40.SVF

[font]
face=ui
missing=u+25a1
align=cell
; ASCII from the same SVF as the Hangul, stepped by its own widths
range.basic-latin=same
advance.basic-latin=font
[font:clut8]
face=iyagi,fb
align=cell
; basic Latin from the game's own font, at the game's widths
range.basic-latin=original
advance.basic-latin=game

; status line, menu bar, parser line, system dialogs: 16 px lines
[font.0:clut8]
face=hterm,fb

[font.1]
face=marus24a,body
size=24
cell=glyph
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game
[font.1:clut8]
face=marus24,hwp,fb
size=24
cell=glyph
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game

[font.4]
face=body
[font.4:clut8]
face=iyagi,fb

; font 7 (the printer's 46 px line) is not drawn in play; its pick is here for completeness
[font.7:clut8]
face=dkbhg40,gh48,fb
size=40
cell=glyph

; the cast names are lined up under the portraits with runs of spaces:
; spaces and Latin keep the game font's widths
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game
[font.8]
face=munjo,fb
advance.basic-latin=game
size=24
cell=glyph
range.basic-latin=original
align=cell
shift=0
[font.8:clut8]
face=munjo,fb
size=24
cell=glyph

; credits and act titles, caption: the game font is 18 game px tall; the
; true-colour glyphs get an 18 px cell (cell=glyph) so they never touch
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game
[font.40]
face=nsqrr36a,body
cell=glyph
size=36
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game
[font.40:clut8]
face=nsqrr36,cap,fb
cell=glyph
size=36
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game

[font.41]
face=nsqrb36a,body
cell=glyph
size=36
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game
[font.41:clut8]
face=nsqrb36,credit,fb
cell=glyph
size=36
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game

[font.7]
face=dkbhg40,ui
size=40
cell=glyph
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game
[load:clut8]
cap=stream
credit=stream

[preload:clut8]
cap=DIPHY36.HOT
credit=YOUTH36.HOT
